def findChampion(grid):
    n = len(grid)  # number of teams

    for i in range(n):
        # Count victories excluding self-match
        victories = 0
        for j in range(n):
            if i != j and grid[i][j] == 1:
                victories += 1

        # If victories equal total opponents, i is champion
        if victories == n - 1:
            return i

    # No champion found
    return -1
